-- The original bank is retained; order is unique within a version, not globally.
alter table public.placement_questions add column if not exists code text;
alter table public.placement_questions add column if not exists level text;
alter table public.placement_questions add column if not exists skill text;
alter table public.placement_questions add column if not exists text_id text;
alter table public.placement_questions add column if not exists reason text;
alter table public.placement_questions add column if not exists version text;
update public.placement_questions set version = 'legacy' where version is null;
alter table public.placement_questions alter column version set default 'legacy';
alter table public.placement_questions alter column version set not null;
alter table public.placement_questions drop constraint if exists placement_questions_sort_order_key;
create unique index if not exists placement_questions_version_order_key on public.placement_questions (version, sort_order);
create unique index if not exists placement_questions_version_code_key on public.placement_questions (version, code);

create table if not exists public.placement_texts (id text primary key, title text not null, type text not null, level text not null, body text not null);
alter table public.placement_texts enable row level security;
revoke all on public.placement_texts from anon, authenticated;
-- Preserve the existing policy name checked by the schema guard, but restrict
-- direct table reads so answer keys and explanations are never public.
alter policy "public read placement questions" on public.placement_questions using (public.is_staff());
revoke select on public.placement_questions from anon;

do $seed$
declare bank jsonb := $bank${"texts":[{"id":"RA","title":"Changes to your evening course","type":"email","level":"B1","text":"Subject: Changes to your evening course\n\nDear students,\n\nFrom Monday 12 January, the Tuesday evening class will move from Room 4 to the new study centre on the second floor of the library building. The class will still start at 7 p.m., but it will now finish at 8.45 instead of 8.30, because the library stays open later in winter.\n\nIf you can't attend at the new time, please tell reception by Friday and we will try to find you a place in the Thursday group. There is no extra cost for the longer lessons.\n\nParking near the library is limited, so we recommend taking the bus. The number 14 stops right outside.\n\nBest wishes,\nHelen Price\nCourse Coordinator"},{"id":"RB","title":"Working from the café","type":"article","level":"B1+","text":"When Tom Harris lost his office last spring, he expected to miss it. His company had decided that staff could work from anywhere, and the city-centre building was sold. 'At first I thought I'd be lonely at home,' he says. 'So I started taking my laptop to a café near my flat.'\n\nSix months later, Tom is one of a growing group of regulars. The owner, Marta, has added more plugs and a 'quiet table' where phone calls are not allowed. 'Some people only buy one coffee and stay all morning,' she admits, 'but on weekdays the café would be empty without them.'\n\nNot everyone is convinced. Tom's manager worries that private conversations can be overheard, and Tom himself admits that it is harder to concentrate when the café is busy. Still, he has no plans to go back to an office. 'I must have spent two hours a day commuting before,' he says. 'Now I walk for five minutes and I've got my evenings back.'"}],"questions":[{"id":"P01","sort_order":1,"skill":"grammar","level":"A2","area":"Past simple","textId":null,"question":"We ___ to Málaga last summer and stayed with my cousin.","options":["go","went","have gone","goes"],"answer_index":1,"reason":"A finished time (last summer) needs the past simple."},{"id":"P02","sort_order":2,"skill":"grammar","level":"A2","area":"Comparatives","textId":null,"question":"The train is fast, but the plane is ___.","options":["more fast","fastest","faster","more faster"],"answer_index":2,"reason":"One-syllable adjectives add -er; 'more' is not used with fast."},{"id":"P03","sort_order":3,"skill":"grammar","level":"A2","area":"have to","textId":null,"question":"In my job I ___ wear a uniform, so I don't choose my clothes.","options":["have to","must to","has to","can"],"answer_index":0,"reason":"Have to expresses an obligation; 'must to' is not English and 'has' doesn't go with I."},{"id":"P04","sort_order":4,"skill":"grammar","level":"B1","area":"Present perfect vs past simple","textId":null,"question":"I ___ in this flat since 2023.","options":["live","lived","am living","have lived"],"answer_index":3,"reason":"Since + a starting point needs the present perfect for a situation that continues now."},{"id":"P05","sort_order":5,"skill":"grammar","level":"B1","area":"Future forms","textId":null,"question":"Look at those dark clouds. It ___ rain.","options":["is raining","is going to","rains","is going"],"answer_index":1,"reason":"Be going to makes a prediction from present evidence (the clouds)."},{"id":"P06","sort_order":6,"skill":"grammar","level":"B1","area":"First conditional","textId":null,"question":"If you ___ the 8.15 train, you'll get there on time.","options":["will catch","would catch","caught","catch"],"answer_index":3,"reason":"In the if-clause of a first conditional we use the present simple, not will."},{"id":"P07","sort_order":7,"skill":"grammar","level":"B1+","area":"Past perfect","textId":null,"question":"When we arrived at the cinema, the film ___, so we missed the beginning.","options":["has already started","had already started","already starts","is already starting"],"answer_index":1,"reason":"The film started before we arrived, an earlier past action: past perfect."},{"id":"P08","sort_order":8,"skill":"grammar","level":"B1+","area":"Second conditional","textId":null,"question":"If I ___ more free time, I'd learn to play the guitar.","options":["have","would have","had","will have"],"answer_index":2,"reason":"An imaginary present situation: if + past simple, would + infinitive."},{"id":"P09","sort_order":9,"skill":"grammar","level":"B2","area":"Reported questions","textId":null,"question":"'Where do you work?' she asked me. → She asked me where ___.","options":["do I work","did I work","I worked","worked I"],"answer_index":2,"reason":"Reported questions use statement word order, and the tense moves back."},{"id":"P10","sort_order":10,"skill":"grammar","level":"B2","area":"Third conditional","textId":null,"question":"If we ___ earlier, we wouldn't have missed the flight.","options":["had left","left","would leave","have left"],"answer_index":0,"reason":"An imaginary past situation: if + past perfect, would have + past participle."},{"id":"P11","sort_order":11,"skill":"vocabulary","level":"A2","area":"Everyday adjectives","textId":null,"question":"I'm really ___. Can we stop for something to eat?","options":["hungry","thirsty","tired","full"],"answer_index":0,"reason":"Wanting something to eat means hungry; thirsty is for drinks and full is the opposite."},{"id":"P12","sort_order":12,"skill":"vocabulary","level":"B1","area":"look forward to + -ing","textId":null,"question":"I'm looking forward ___ you next week.","options":["see","to see","to seeing","seeing"],"answer_index":2,"reason":"In look forward to, 'to' is a preposition, so it is followed by the -ing form."},{"id":"P13","sort_order":13,"skill":"vocabulary","level":"B1","area":"Collocation: do","textId":null,"question":"Can you ___ me a favour and post this letter?","options":["make","do","give","take"],"answer_index":1,"reason":"The fixed phrase is do someone a favour."},{"id":"P14","sort_order":14,"skill":"vocabulary","level":"B1+","area":"Collocation: make","textId":null,"question":"She's ___ a lot of progress with her English this year.","options":["done","made","got","taken"],"answer_index":1,"reason":"The collocation is make progress."},{"id":"P15","sort_order":15,"skill":"vocabulary","level":"B1+","area":"-ed / -ing adjectives","textId":null,"question":"I've been working since 7 a.m., so I'm completely ___.","options":["exhausting","tiring","exhausted","exhaust"],"answer_index":2,"reason":"-ed adjectives describe how a person feels; -ing adjectives describe what causes the feeling."},{"id":"P16","sort_order":16,"skill":"vocabulary","level":"B2","area":"manage to","textId":null,"question":"Despite the rain, the festival ___ to attract over 10,000 visitors.","options":["succeeded","could","achieved","managed"],"answer_index":3,"reason":"Manage to + infinitive means succeed in doing something difficult; succeed needs 'in attracting'."},{"id":"P17","sort_order":17,"skill":"reading","level":"A2","area":"Specific information","textId":"RA","question":"Where will the Tuesday class be from 12 January?","options":["On the second floor of the library building","In Room 4","At reception","In the Thursday group's room"],"answer_index":0,"reason":"'will move from Room 4 to the new study centre on the second floor of the library building'."},{"id":"P18","sort_order":18,"skill":"reading","level":"B1","area":"Detail: what changes","textId":"RA","question":"What changes about the lesson time?","options":["It starts earlier.","It finishes later.","It starts later.","It moves to another day."],"answer_index":1,"reason":"It 'will still start at 7 p.m.' but 'finish at 8.45 instead of 8.30'."},{"id":"P19","sort_order":19,"skill":"reading","level":"B1","area":"Reason","textId":"RA","question":"Why will the lessons finish later?","options":["The library is open for longer in winter.","The lessons cost more now.","Students asked for longer lessons.","The bus timetable has changed."],"answer_index":0,"reason":"'because the library stays open later in winter'."},{"id":"P20","sort_order":20,"skill":"reading","level":"B1+","area":"Inference: what to do","textId":"RA","question":"A student can't stay until 8.45. What should they do?","options":["Pay for a shorter lesson.","Take the number 14 bus.","Go to the Thursday group on 12 January.","Contact reception before the end of the week."],"answer_index":3,"reason":"'please tell reception by Friday'; the Thursday place is not guaranteed and has to be arranged first."},{"id":"P21","sort_order":21,"skill":"reading","level":"A2","area":"Specific information","textId":"RB","question":"Why did Tom stop working in an office?","options":["He moved to a new flat.","He lost his job.","His company sold the building.","The café offered him work."],"answer_index":2,"reason":"'the city-centre building was sold' when staff could work from anywhere; he kept his job."},{"id":"P22","sort_order":22,"skill":"reading","level":"B1","area":"Detail","textId":"RB","question":"What has Marta done for people who work in her café?","options":["She has made a table for quiet work.","She has lowered her prices.","She has started opening at weekends.","She has stopped people using laptops."],"answer_index":0,"reason":"She 'has added more plugs and a quiet table where phone calls are not allowed'."},{"id":"P23","sort_order":23,"skill":"reading","level":"B1+","area":"Attitude","textId":"RB","question":"How does Marta feel about the people who work in her café?","options":["She is annoyed because they spend very little.","She is happy because they bring customers on quiet days.","She is worried that they are too noisy.","She only lets them stay at weekends."],"answer_index":1,"reason":"She 'admits' they buy little, but 'on weekdays the café would be empty without them'."},{"id":"P24","sort_order":24,"skill":"reading","level":"B2","area":"Modals of deduction","textId":"RB","question":"'I must have spent two hours a day commuting before.' What does Tom mean?","options":["He had to commute for two hours by law.","He wants to commute for two hours.","He never really commuted.","He is fairly sure he spent about two hours a day."],"answer_index":3,"reason":"Must have + past participle shows a confident guess about the past, not an obligation."}]}$bank$::jsonb;
begin
  insert into public.placement_texts (id,title,type,level,body)
  select x->>'id',x->>'title',x->>'type',x->>'level',x->>'text' from jsonb_array_elements(bank->'texts') x
  on conflict (id) do update set title=excluded.title, type=excluded.type, level=excluded.level, body=excluded.body;
  insert into public.placement_questions (sort_order,code,level,skill,text_id,reason,version,source,area,question,options,answer_index,active)
  select (x->>'sort_order')::smallint,x->>'id',x->>'level',x->>'skill',x->>'textId',x->>'reason','v2','v2',x->>'area',x->>'question',x->'options',(x->>'answer_index')::smallint,true
  from jsonb_array_elements(bank->'questions') x
  on conflict (version,sort_order) do update set code=excluded.code,level=excluded.level,skill=excluded.skill,text_id=excluded.text_id,reason=excluded.reason,source=excluded.source,area=excluded.area,question=excluded.question,options=excluded.options,answer_index=excluded.answer_index,active=true;
end $seed$;

create or replace view public.placement_questions_safe as
  select id, sort_order, area, question, options, code, level, skill, text_id, version
  from public.placement_questions where active and version='v2';
grant select on public.placement_questions_safe to anon, authenticated;
create or replace view public.placement_texts_safe as select id,title,type,level,body from public.placement_texts;
grant select on public.placement_texts_safe to anon, authenticated;
